package javaactions

import (
	"reflect"
	"testing"
)

// The marketplace NanoflowCommons ships its .js with the imports above the
// banner and no blank lines; Studio Pro's own stub puts them below it. Both,
// and imports without semicolons, are the import list (mendixlabs/mxcli#1429).
func TestJavaScriptRetainedSections(t *testing.T) {
	src := "import { Big } from \"big.js\"\n" +
		"import 'mx-global'\n\n" +
		"// This file was generated by Mendix Studio Pro.\n" +
		"// begin extra code\n" +
		"function deg2rad(deg) {\n    return deg;\n}\n" +
		"// End Extra Code\n" +
		"/**\n * @returns {Promise.<Big>}\n */\n" +
		"export async function F() {\n\t// BEGIN USER CODE\n\timport('x');\n\t// END USER CODE\n}\n"
	imports, extra := JavaScriptRetainedSections(src)
	if want := []string{`import { Big } from "big.js"`, `import 'mx-global'`}; !reflect.DeepEqual(imports, want) {
		t.Errorf("imports = %q, want %q", imports, want)
	}
	if want := "function deg2rad(deg) {\n    return deg;\n}"; extra != want {
		t.Errorf("extra = %q, want %q", extra, want)
	}
	if imports, extra := JavaScriptRetainedSections(""); imports != nil || extra != "" {
		t.Errorf("no file: got %q, %q", imports, extra)
	}
}
